<?php
$pdo=db();$canManage=in_array($user['role'],['Administrator','Head'],true);$date=(string)($_GET['date']??date('Y-m-d'));$dateObj=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$dateErrors=DateTimeImmutable::getLastErrors();if($dateObj===false||$dateObj->format('Y-m-d')!==$date||($dateErrors!==false&&($dateErrors['warning_count']||$dateErrors['error_count']))||$date>date('Y-m-d'))$date=date('Y-m-d');$staff=[];$attendance=[];$leaveRequests=[];$leaveHistory=[];
try{if($canManage){$staff=$pdo->query("SELECT id,full_name,role FROM users WHERE active=1 AND role IN ('Administrator','Head','Teacher','Bursar','Clerk') ORDER BY FIELD(role,'Head','Teacher','Bursar','Clerk','Administrator'),full_name")->fetchAll();$q=$pdo->prepare('SELECT sa.*,u.full_name,u.role FROM staff_attendance sa JOIN users u ON u.id=sa.staff_id WHERE attendance_date=:date ORDER BY u.full_name');$q->execute(['date'=>$date]);foreach($q->fetchAll() as $row)$attendance[(int)$row['staff_id']]=$row;$q=$pdo->prepare("SELECT staff_id FROM staff_leave_requests WHERE status='Approved' AND start_on<=:date AND end_on>=:date");$q->execute(['date'=>$date]);$approvedLeave=array_fill_keys(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)),true);$q=$pdo->prepare('SELECT r.*,u.full_name,u.role FROM staff_leave_requests r JOIN users u ON u.id=r.staff_id ORDER BY FIELD(r.status,\'Pending\',\'Approved\',\'Declined\',\'Cancelled\'),r.start_on DESC,r.id DESC LIMIT 100');$q->execute();$leaveRequests=$q->fetchAll();}else{$approvedLeave=[];$q=$pdo->prepare('SELECT r.*,u.full_name,u.role FROM staff_leave_requests r JOIN users u ON u.id=r.staff_id WHERE r.staff_id=:user ORDER BY r.created_at DESC,r.id DESC LIMIT 100');$q->execute(['user'=>$user['id']]);$leaveRequests=$q->fetchAll();}if($leaveRequests){$ids=array_map('intval',array_column($leaveRequests,'id'));$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT h.leave_request_id,h.from_status,h.to_status,h.notes,h.created_at,u.full_name FROM staff_leave_reviews h LEFT JOIN users u ON u.id=h.reviewed_by WHERE h.leave_request_id IN ($marks) ORDER BY h.created_at DESC,h.id DESC");$q->execute($ids);foreach($q->fetchAll() as $r)$leaveHistory[$r['leave_request_id']][]=$r;}$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM users WHERE active=1 AND role IN ('Administrator','Head','Teacher','Bursar','Clerk')) AS staff_count,(SELECT COUNT(*) FROM staff_attendance WHERE attendance_date=CURDATE() AND status IN ('Present','Late')) AS present_today,(SELECT COUNT(*) FROM staff_leave_requests WHERE status='Pending') AS pending_leave")->fetch();}catch(Throwable $e){error_log('Staffing page failed: '.$e->getMessage());echo '<section class="panel settings-panel"><h1>Staffing setup required</h1><p>An administrator should import <code>database/migrations/015_staffing.sql</code> into the school database, then reload this page.</p></section>';return;}
?>
<div class="page-heading"><div><div class="eyebrow">SCHOOL PERSONNEL</div><h1>Staffing</h1><p class="subheading">Record daily staff attendance and manage leave requests with a review history.</p></div></div>
<section class="stat-strip"><div><span>Active staff accounts</span><b><?= number_format((int)$stats['staff_count']) ?></b></div><?php if($canManage): ?><div><span>Present / late today</span><b><?= number_format((int)$stats['present_today']) ?></b></div><div><span>Pending leave requests</span><b><?= number_format((int)$stats['pending_leave']) ?></b></div><?php else: ?><div><span>Your leave requests</span><b><?= number_format(count($leaveRequests)) ?></b></div><?php endif; ?><div><span>Register date</span><b><?= h(date('d M Y',strtotime($date))) ?></b></div></section>
<?php if($canManage): ?><section class="panel settings-panel"><div class="panel-heading"><div><h2>Daily staff attendance</h2><p>Leave a row at “Not recorded” to make no change. Approved leave is suggested for that date.</p></div></div><form method="get" class="compact-form"><input type="hidden" name="page" value="staffing"><label>Register date<input type="date" name="date" max="<?= h(date('Y-m-d')) ?>" value="<?= h($date) ?>" required></label><button class="outline-button">Load date</button></form><form method="post" action="actions/staff_attendance_save.php"><?= csrf_field() ?><input type="hidden" name="attendance_date" value="<?= h($date) ?>"><div class="table-scroll"><table class="data-table"><thead><tr><th>Staff member</th><th>Role</th><th>Status</th><th>Check in</th><th>Check out</th><th>Note</th></tr></thead><tbody><?php foreach($staff as $person): $row=$attendance[(int)$person['id']]??null;$defaultStatus=$row['status']??(isset($approvedLeave[(int)$person['id']])?'On Leave':''); ?><tr><td><?= h($person['full_name']) ?></td><td><?= h($person['role']) ?></td><td><select name="staff[<?= (int)$person['id'] ?>][status]"><option value="">Not recorded</option><?php foreach(['Present','Late','Absent','On Leave','Off Duty'] as $status): ?><option value="<?= h($status) ?>" <?= $defaultStatus===$status?'selected':'' ?>><?= h($status) ?></option><?php endforeach; ?></select></td><td><input type="time" name="staff[<?= (int)$person['id'] ?>][check_in]" value="<?= h($row['check_in']??'') ?>"></td><td><input type="time" name="staff[<?= (int)$person['id'] ?>][check_out]" value="<?= h($row['check_out']??'') ?>"></td><td><input name="staff[<?= (int)$person['id'] ?>][note]" maxlength="255" value="<?= h($row['note']??'') ?>"></td></tr><?php endforeach; if(!$staff): ?><tr><td colspan="6" class="empty-cell">No active staff accounts are configured.</td></tr><?php endif; ?></tbody></table></div><div class="form-actions"><button class="primary-button">Save staff register</button></div></form></section><?php endif; ?>
<section class="panel settings-panel"><div class="panel-heading"><div><h2>Request leave</h2><p>Leave requests are visible to you and school leadership.</p></div></div><form method="post" action="actions/staff_leave_submit.php" class="compact-form"><?= csrf_field() ?><label>Leave type<select name="leave_type" required><?php foreach(['Annual','Sick','Maternity','Paternity','Compassionate','Study','Unpaid','Other'] as $type): ?><option><?= h($type) ?></option><?php endforeach; ?></select></label><label>Start date<input type="date" name="start_on" required></label><label>End date<input type="date" name="end_on" required></label><label class="full-width">Reason / handover note <span class="optional">Optional; avoid detailed medical information</span><textarea name="reason" rows="2" maxlength="1000"></textarea></label><button class="primary-button">Submit leave request</button></form></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2><?= $canManage?'Staff leave register':'Your leave requests' ?></h2><p><?= count($leaveRequests) ?> requests shown · maximum 100</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><?php if($canManage): ?><th>Staff member</th><?php endif; ?><th>Leave</th><th>Dates</th><th>Reason</th><th>Status / history</th><?php if($canManage): ?><th>Review</th><?php else: ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach($leaveRequests as $request): ?><tr><?php if($canManage): ?><td><?= h($request['full_name']) ?><br><span class="muted-cell"><?= h($request['role']) ?></span></td><?php endif; ?><td><?= h($request['leave_type']) ?></td><td><?= h(date('d M Y',strtotime($request['start_on']))) ?> – <?= h(date('d M Y',strtotime($request['end_on']))) ?></td><td><?= $request['reason']?nl2br(h($request['reason'])):'—' ?></td><td><span class="status-pill"><?= h($request['status']) ?></span><?php if($request['reviewed_at']): ?><br><span class="muted-cell">Reviewed <?= h(date('d M Y',strtotime($request['reviewed_at']))) ?></span><?php endif; ?><?php if(!empty($leaveHistory[$request['id']])): ?><details><summary>History</summary><?php foreach($leaveHistory[$request['id']] as $event): ?><p><?= h(date('d M Y H:i',strtotime($event['created_at']))) ?> · <?= h($event['from_status']?:'New') ?> → <?= h($event['to_status']) ?><br><?= h($event['full_name']??'Former staff') ?><?= $event['notes']?': '.h($event['notes']):'' ?></p><?php endforeach; ?></details><?php endif; ?></td><td><?php if($canManage&&$request['status']==='Pending'): ?><form method="post" action="actions/staff_leave_review.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><label>Review note <span class="optional">Required for decline</span><input name="notes" maxlength="500"></label><button class="primary-button" name="status" value="Approved">Approve</button><button class="outline-button" name="status" value="Declined" onclick="return confirm('Decline this leave request?')">Decline</button></form><?php elseif(!$canManage&&$request['status']==='Pending'&&(int)$request['staff_id']===(int)$user['id']): ?><form method="post" action="actions/staff_leave_cancel.php" onsubmit="return confirm('Cancel this pending leave request?')"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="outline-button compact-button">Cancel request</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; if(!$leaveRequests): ?><tr><td colspan="<?= $canManage?6:5 ?>" class="empty-cell">No leave requests have been recorded.</td></tr><?php endif; ?></tbody></table></div></section>
